using System.Collections.Generic;
using UnityEngine;
namespace VRBat {
public static class BatGeometry {
 public static Shader LitShader;
 static readonly Dictionary<string,Material> materials=new Dictionary<string,Material>();
 public static Color ColorOf(string hex){ColorUtility.TryParseHtmlString(hex,out var c);return c;}
 public static Material Material(string hex,bool metal=false){string key=hex+(metal?"M":"D");if(materials.TryGetValue(key,out var cached)&&cached)return cached;var m=new Material(LitShader ? LitShader : Shader.Find("Universal Render Pipeline/Lit"));materials[key]=m;m.color=ColorOf(hex);m.SetFloat("_Metallic",metal?.65f:0);m.SetFloat("_Smoothness",metal?.7f:.25f);return m;}
 public static GameObject Box(string name,Vector3 p,Vector3 size,Material m,Transform parent=null){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(parent,false);o.transform.localPosition=p;o.transform.localScale=size;o.GetComponent<Renderer>().sharedMaterial=m;return o;}
 public static GameObject Sphere(string name,Vector3 p,Vector3 size,Material m,Transform parent=null){var o=GameObject.CreatePrimitive(PrimitiveType.Sphere);o.name=name;o.transform.SetParent(parent,false);o.transform.localPosition=p;o.transform.localScale=size;o.GetComponent<Renderer>().sharedMaterial=m;Object.Destroy(o.GetComponent<Collider>());return o;}
 public static GameObject MeshObject(string name,List<Vector3> v,List<int> tr,Material m,Transform parent=null){var o=new GameObject(name);o.transform.SetParent(parent,false);var mesh=new Mesh{name=name};mesh.SetVertices(v);mesh.SetTriangles(tr,0);mesh.RecalculateNormals();mesh.RecalculateBounds();o.AddComponent<MeshFilter>().sharedMesh=mesh;o.AddComponent<GeneratedMeshOwner>().mesh=mesh;o.AddComponent<MeshRenderer>().sharedMaterial=m;return o;}
 public static GameObject Lathe(string name,float[] ys,float[] rs,Material m,Transform parent=null,int segments=24){var v=new List<Vector3>();var tr=new List<int>();for(int j=0;j<ys.Length;j++)for(int i=0;i<=segments;i++){float a=2*Mathf.PI*i/segments;v.Add(new Vector3(Mathf.Cos(a)*rs[j],ys[j],Mathf.Sin(a)*rs[j]));}for(int j=0;j<ys.Length-1;j++)for(int i=0;i<segments;i++){int a=j*(segments+1)+i,b=a+segments+1;tr.AddRange(new[]{a,b,a+1,a+1,b,b+1});}return MeshObject(name,v,tr,m,parent);}
 public static GameObject Ring(string name,Vector3 p,float radius,float width,Material m,Transform parent=null,bool horizontal=false){var o=new GameObject(name);o.transform.SetParent(parent,false);o.transform.localPosition=p;var l=o.AddComponent<LineRenderer>();l.useWorldSpace=false;l.loop=true;l.positionCount=64;l.widthMultiplier=width;l.sharedMaterial=m;for(int i=0;i<64;i++){float a=i*Mathf.PI/32;l.SetPosition(i,horizontal?new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius):new Vector3(Mathf.Cos(a)*radius,Mathf.Sin(a)*radius,0));}return o;}
 public static LineRenderer Line(string name,Vector3[] points,float width,Material m,Transform parent=null){var o=new GameObject(name);o.transform.SetParent(parent,false);var l=o.AddComponent<LineRenderer>();l.useWorldSpace=false;l.positionCount=points.Length;l.SetPositions(points);l.widthMultiplier=width;l.sharedMaterial=m;return l;}
 public static GameObject Normalize(GameObject prefab,string name,Vector3 size,bool bottom,Transform parent=null,bool uniform=false,int child=-1){
 var root=new GameObject(name);root.transform.SetParent(parent,false);var content=new GameObject("Normalized source");content.transform.SetParent(root.transform,false);var model=Object.Instantiate(prefab,content.transform);model.name="Original";
 foreach(var animation in model.GetComponentsInChildren<Animation>()){animation.playAutomatically=false;animation.Stop();foreach(AnimationState state in animation)if(state.name=="open"){state.normalizedTime=0;state.enabled=true;animation.Sample();state.enabled=false;break;}}
 if(child>=0){var children=new List<Transform>();foreach(Transform t in model.transform)children.Add(t);for(int i=0;i<children.Count;i++)if(i!=child)Object.DestroyImmediate(children[i].gameObject);model.transform.localRotation=Quaternion.Euler(0,-90,0);}
 if(prefab.name=="chest")model.transform.localRotation=Quaternion.Euler(0,180,0);
 var renderers=model.GetComponentsInChildren<Renderer>();var bounds=new Bounds();bool first=true;foreach(var r in renderers){var local=new Bounds(root.transform.InverseTransformPoint(r.bounds.center),r.bounds.size/root.transform.lossyScale.x);if(first){bounds=local;first=false;}else bounds.Encapsulate(local);}var b=bounds.size;var scale=new Vector3(b.x>.00001?size.x/b.x:1,b.y>.00001?size.y/b.y:1,b.z>.00001?size.z/b.z:1);if(uniform)scale=Vector3.one*(size.x>0?scale.x:scale.y);content.transform.localScale=scale;var pivot=bottom?new Vector3(bounds.center.x,bounds.min.y,bounds.center.z):bounds.center;content.transform.localPosition=-Vector3.Scale(pivot,scale);return root;
 }
 public static GameObject Gem(string name,Vector3 size,Material material,Transform parent){var v=new List<Vector3>{new Vector3(0,size.y/2,0),new Vector3(0,-size.y/2,0),new Vector3(size.x/2,0,0),new Vector3(0,0,size.z/2),new Vector3(-size.x/2,0,0),new Vector3(0,0,-size.z/2)};var tr=new List<int>{0,3,2,0,4,3,0,5,4,0,2,5,1,2,3,1,3,4,1,4,5,1,5,2};return MeshObject(name,v,tr,material,parent);}
 public static float Radius(float s){if(s<-.10f)return .03f;if(s<.12f)return .016f;if(s<.30f)return Mathf.Lerp(.016f,.039f,(s-.12f)/.18f);if(s<=.70f)return .039f;return Mathf.Lerp(.039f,.026f,(s-.70f)/.03f);}
 public static GameObject Bat(Material silver,Material grip,Material band){var root=new GameObject("Bat");Lathe("Grip end",new[]{-.12f,-.12f,-.10f,-.10f},new[]{0f,.03f,.03f,0},grip,root.transform);Lathe("Grip",new[]{-.10f,.12f},new[]{.016f,.016f},grip,root.transform);Lathe("Barrel",new[]{.12f,.30f,.43f,.68f,.70f,.72f,.73f,.73f},new[]{.016f,.039f,.039f,.039f,.039f,.034f,.026f,0},silver,root.transform);Lathe("Sweet band",new[]{.43f,.68f},new[]{.0391f,.0391f},band,root.transform);foreach(float y in new[]{.432f,.438f,.672f,.678f})Ring("Band double line",new Vector3(0,y,0),.0393f,.0015f,grip,root.transform,true);for(int i=0;i<6;i++)Ring("Grip groove",new Vector3(0,-.075f+i*.032f,0),.0161f,.003f,silver,root.transform,true);Sphere("Mitten palm",Vector3.zero,new Vector3(.075f,.10f,.045f),Material("#F0ECE2"),root.transform);Sphere("Thumb",new Vector3(.035f,.015f,0),new Vector3(.036f,.05f,.036f),Material("#F0ECE2"),root.transform);Ring("Wrist",new Vector3(0,-.05f,0),.0325f,.008f,grip,root.transform,true);return root;}
 // Test visible tapered bat surfaces, not an enlarged invisible slab.
 public static bool SphereContact(Vector3 center,float radius,Vector3 grip,Vector3 axis,out float s,out Vector3 surface){s=Mathf.Clamp(Vector3.Dot(center-grip,axis),-.12f,.73f);var a=grip+s*axis;var delta=center-a;surface=a+delta.normalized*Radius(s);return delta.sqrMagnitude<=Mathf.Pow(radius+Radius(s),2);}
 public static bool BoxContact(Bounds box,Vector3 grip,Vector3 axis,out float s){for(int i=0;i<=100;i++){s=-.12f+.85f*i/100;var p=grip+s*axis;if((p-box.ClosestPoint(p)).sqrMagnitude<=Radius(s)*Radius(s))return true;}s=0;return false;}
 public static float BoxDistance(Bounds box,Vector3 grip,Vector3 axis){float best=float.PositiveInfinity;for(int i=0;i<=170;i++){float s=-.12f+.85f*i/170;var p=grip+s*axis;best=Mathf.Min(best,Vector3.Distance(p,box.ClosestPoint(p))-Radius(s));}return best;}
 public static bool SweepSphere(Vector3 from,Vector3 to,float radius,Vector3 oldGrip,Vector3 oldAxis,Vector3 grip,Vector3 axis,out float s){float distance=(to-from).magnitude+(grip-oldGrip).magnitude+.85f*(axis-oldAxis).magnitude;int steps=Mathf.Max(1,Mathf.CeilToInt(distance/.005f));for(int i=0;i<=steps;i++){float t=(float)i/steps;if(SphereContact(Vector3.Lerp(from,to,t),radius,Vector3.Lerp(oldGrip,grip,t),Vector3.Slerp(oldAxis,axis,t),out s,out _))return true;}s=0;return false;}
 public static GameObject Worktop(Material m,Transform parent){var v=new List<Vector3>();var tr=new List<int>();const int n=192;Vector2 c=new Vector2(-.48f,.78f);for(int i=0;i<=n;i++){float a=i*2*Mathf.PI/n;var d=new Vector2(Mathf.Cos(a),Mathf.Sin(a));float tx=(d.x>=0?.8f-c.x:-.8f-c.x)/d.x;float tz=(d.y>=0?1.12f-c.y:.32f-c.y)/d.y;float t=Mathf.Min(tx,tz);Vector2 outer=c+d*t,inner=c+d*.22f;v.Add(new Vector3(inner.x,.88f,inner.y));v.Add(new Vector3(outer.x,.88f,outer.y));v.Add(new Vector3(inner.x,.78f,inner.y));v.Add(new Vector3(outer.x,.78f,outer.y));}for(int i=0;i<n;i++){int a=i*4,b=a+4;tr.AddRange(new[]{a,b,a+1,a+1,b,b+1,a+2,a+3,b+2,a+3,b+3,b+2,a,a+2,b,a+2,b+2,b,a+1,b+1,a+3,a+3,b+1,b+3});}var o=MeshObject("Worktop actual through hole",v,tr,m,parent);o.AddComponent<MeshCollider>().sharedMesh=o.GetComponent<MeshFilter>().sharedMesh;return o;}
}
}
